// Keep only the new part of the reply: drop quoted history and signatures,
// so the model reads what the customer actually wrote this time.
const raw = ($json.text || '').replace(/\r\n/g, '\n');
const cutAt = [
  /^On\b[\s\S]{0,200}?wrote:/m,          // Gmail, Apple Mail (can wrap over 2 lines)
  /^-{2,}\s*Original Message\s*-{2,}/mi, // Outlook
  /^From: .+$/m,                         // Outlook quoted header block
  /^_{5,}/m,                             // Outlook separator line
  /^--\s*$/m,                            // standard signature delimiter
  /^Sent from my /m,                     // mobile footers
];
let body = raw;
for (const re of cutAt) {
  const m = body.match(re);
  if (m && m.index > 0) body = body.slice(0, m.index);
}
body = body.split('\n').filter(l => !l.trimStart().startsWith('>')).join('\n').trim();
if (!body) body = raw.trim(); // never send an empty reply: fall back to the full text

const max = Number($json.maxReplyChars) || 3000;
const from = $json.from?.value?.[0] ?? {};
return {
  json: {
    messageId: $json.id,
    threadId: $json.threadId,
    fromEmail: from.address || '',
    subject: $json.subject || '',
    receivedAt: $json.date,
    reply: body.slice(0, max), // long replies are cut to keep cost predictable
  },
};

